import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"通胀挂钩","description":"","frontmatter":{"title":"通胀挂钩","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/inflation-linked.md","filePath":"quant/inflation-linked.md","lastUpdated":1789023840000}'),B={name:"quant/inflation-linked.md"};function c(I,a,P,h,A,m){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="通胀挂钩" tabindex="-1">通胀挂钩 <a class="header-anchor" href="#通胀挂钩" aria-label="Permalink to &quot;通胀挂钩&quot;">​</a></h1><div class="epigraph"><p>TIPS 与通胀互换交换的是 CPI 的约定滞后；零息通胀互换的价格定义实际贴现曲线，而不是「预期通胀」四个字。</p><footer>—— Jarrow and Yildirim, Pricing Treasury Inflation Protected Securities and Related Derivatives, Journal of Financial and Quantitative Analysis, 2003</footer></div><p><a href="/quant/weather-power-derivatives">上一课</a>的指数不可交易。通胀挂钩把 CPI 推进利率市场：TIPS、零息与年度通胀互换、通胀 cap/floor。缺口是<strong>实际利率与名义利率的联合建模</strong>，以及公布滞后、季节调整。主干曲线课已有名义 <a href="/quant/curve-bootstrap">Bootstrap</a>。本课不重写名义曲线，只把实际曲线与 BEI（盈亏平衡通胀）接上，后课 caps 再用名义 vol。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>零息通胀互换：到期按 \\(\\mathrm{CPI}_T/\\mathrm{CPI}_0-1\\) 对固定 \\(K\\) 结算（有滞后）。其公平 \\(K\\) 定义一条实际折现与名义折现的比。BEI 是名义与 TIPS 收益率之差，含流动性与通胀风险溢价，<strong>不是</strong>调查预期。问题是衍生品：yoY cap 写在年度通胀率上，需要 CPI 的动态，不是一个 BEI 点。Jarrow–Yildirim 用外汇类比：实际利率当「外国利率」，CPI 当汇率，名义当本币——于是 GK 式的三曲线加上实际与名义的相关。</p><p>滞后与季节：CPI 公布滞后若干月，互换用约定的参考指数。季节调整与未季调指数会让短端 yoY 噪声极大，校准短端 cap 要用指数惯例而不是光滑扩散。</p><h3 id="cpi-不是-gbm-现货" tabindex="-1">CPI 不是 GBM 现货 <a class="header-anchor" href="#cpi-不是-gbm-现货" aria-label="Permalink to &quot;CPI 不是 GBM 现货&quot;">​</a></h3><p>CPI 水平近似积分的通胀率，短期不可交易（除了互换）。库存套利不存在。JY 模型借用 FX 的完整市场叙述，是为了得到闭式，不是因为你可以 Delta 到「CPI 现货」。对冲工具是 TIPS、通胀互换与名义互换，基差（TIPS vs 互换）是一等风险。</p><p><span class="marginnote">欧洲 HICP 与美国 CPI-U、英国 RPI/CPIH 的定义不同，季节与住房权重不同。曲面不能跨指数拼接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准：名义 OIS/政府曲线、TIPS 或通胀互换曲线、可选的通胀 vol（cap/floor 或期权）。JY 或市值模型（例如带微笑的 yoY 市场模型）生成 yoY 率。Cap/floor 用类似名义 cap 的 Black 或移位 Black，后课与负利率衔接——欧元区已出现负通胀与负实际利率。对冲：实际 DV01、名义 DV01、BEI 桶、滞后公布的缺口风险。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>名义零息债 = 实际零息债 × CPI 因子（理想化）。通胀互换把 CPI 因子做成可交易。期权再把 CPI 因子的波动卖掉。相关：名义利率升、通胀升时，实际利率的残差才是 TIPS 的独特风险。JY 把这写成三因子 Vasicek 型；生产更常用市场模型直接对 yoY 率建模，以便校准 cap。</p>',13)),(e(),s(p,null,{default:o(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Nom%5B%22%E5%90%8D%E4%B9%89%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20BEI%5B%22%E7%9B%88%E4%BA%8F%E5%B9%B3%E8%A1%A1%20%E5%90%AB%E6%BA%A2%E4%BB%B7%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20Real%5B%22%E5%AE%9E%E9%99%85%E6%9B%B2%E7%BA%BF%20TIPS%20%E6%88%96%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20BEI%0A%20%20BEI%20--%3E%20YoY%5B%22%E5%B9%B4%E5%BA%A6%E9%80%9A%E8%83%80%E7%8E%87%E5%8A%A8%E6%80%81%22%5D%0A%20%20YoY%20--%3E%20Cap%5B%22%E9%80%9A%E8%83%80%20cap%20floor%22%5D%0A%20%20Lag%5B%22%E5%85%AC%E5%B8%83%E6%BB%9E%E5%90%8E%E4%B8%8E%E5%AD%A3%E8%8A%82%22%5D%20--%3E%20YoY%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TIPS 流动性溢价使 BEI 低于互换隐含通胀，拆解必须分开。通缩地板（TIPS 本金地板）是嵌入期权，低通胀时有价值。LDI 与养老金的需求会把实际利率压到与「预期」无关的水平。本课不写宏观预测 CPI；对象是曲线与期权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>通胀互换定义实际/名义的相对曲线；BEI 不是纯预期。</li><li>yoY cap 需要 CPI 动态；JY 是 FX 类比闭式，对冲仍用 TIPS 与互换。</li><li>滞后、季节、指数定义是合约状态。</li><li>出处：Jarrow and Yildirim, <em>JFQA</em>, 2003。</li></ul>',4))])}const f=i(B,[["render",c]]);export{_ as __pageData,f as default};
